HEAD_JS = 'const sym = Symbol("s"), obj = {}, fn = function () {}; class Rec { constructor(n) { this.n = n; } } const typed = new Rec(1);\n'
HEAD_TS = 'const sym = Symbol("s"), obj = {}, fn = function () {}; class Rec { n: number; constructor(n: number) { this.n = n; } } const typed = new Rec(1);\n'
BODY = 'const values%s = [%s];\nfunction loose(a%s, b%s) { return a == b; } function notLoose(a%s, b%s) { return a != b; } function strict(a%s, b%s) { return a === b; } function same(a%s, b%s) { return Object.is(a, b); } function truthy(a%s) { return a ? 1 : 0; } function not(a%s) { return !a; } function both(a%s, b%s) { return a && b ? 1 : 0; }\nconst letter = (f%s) => { try { return f() ? "1" : "0"; } catch (e) { return "T"; } };\nfor (let round = 0; round < 3; round++) for (let i = 0; i < values.length; i++) { let line = ""; for (let j = 0; j < values.length; j++) { const a = values[i], b = values[j]; line += letter(() => loose(a, b)) + letter(() => notLoose(a, b)) + letter(() => strict(a, b)) + letter(() => same(a, b)) + letter(() => both(a, b)) + " "; } if (round === 2) console.log(i, letter(() => truthy(values[i])) + letter(() => not(values[i])), line); }\n'
