open(out + "/equality-untyped/main.js", "w").write(HEAD_JS + BODY % (('', ', '.join(VALUES)) + ('',) * 13))
open(out + "/equality-any/main.ts", "w").write('declare const console: { log(...values: unknown[]): void };\n' + HEAD_TS + BODY % ((': any[]', ', '.join(VALUES)) + (': any',) * 12 + (': () => unknown',)))
RX = '''const seen = () => [RegExp.$1, RegExp.$2, RegExp.$9, RegExp.lastMatch, RegExp["$&"], RegExp.lastParen, RegExp["$+"], RegExp.leftContext, RegExp["$`"], RegExp.rightContext, RegExp["$'"], RegExp.input, RegExp.$_].map(v => JSON.stringify(v)).join();
const plain = /b(c)(d)?/, global = /b(c)/g, sticky = /b(c)/y, named = /(?<x>b)(?<y>c)/, insensitive = /B(C)/i, unicode = /\\u{4e00}(.)/u, one = /c/, empty = /(?:)/, look = /(?<=a)b(?=c)/, dot = /./s;
function test(re, s) { return re.test(s); }
const subjects = ["abcde", "xxabcdbc", "", "c", "ABC", "\\u4e00z", ("ab" + ["cd"][0]), ("zzabcd".slice(2)), "nothing here", "bcbcbc"];
for (let round = 0; round < 3; round++) for (const [name, re] of Object.entries({ plain, global, sticky, named, insensitive, unicode, one, empty, look, dot })) for (const s of subjects) { const found = test(re, s); if (round === 2) console.log(name, JSON.stringify(s), found, re.lastIndex, seen()); }
plain.test("abcd"); const kept = seen(); if (typeof gc === "function") gc(); else if (typeof Bun !== "undefined") Bun.gc(true); console.log(kept === seen());
plain.test("abcd"); "zzz".replace(/z/, "y"); console.log(seen()); plain.test("abcd"); /q/.test("abcd"); console.log(seen()); plain.test("abcd"); "a-b".split(/-/); console.log(seen()); plain.test("abcd"); /(x)(y)/.exec("wxyz"); console.log(seen());
RegExp.input = "set by hand"; console.log(RegExp.input, RegExp.$_); plain.test("abcd"); console.log(RegExp.input);
class Sub extends RegExp { exec(s) { console.log("the exec of Sub"); return super.exec(s); } } console.log(test(new Sub("b(c)"), "abc"), seen());
const own = /b(c)/; own.exec = function (s) { console.log("an own exec"); return null; }; console.log(test(own, "abc"), seen());
for (const bad of [undefined, null, 5, {}, { toString() { return "abcd"; } }, Symbol.iterator]) { try { console.log(test(plain, bad), seen()); } catch (e) { console.log(e.name); } }
'''
os.makedirs(out + "/legacy-regexp-properties", exist_ok=True); open(out + "/legacy-regexp-properties/main.js", "w").write(RX)
BV = '''var root = typeof globalThis == "object" && globalThis, context = root;
var Array_ = context.Array, Object_ = context.Object, Math_ = context.Math, isArray = Array_.isArray, hasOwnProperty = Object_.prototype.hasOwnProperty, nativeMax = Math_.max, nativeMin = Math_.min, nativeKeys = Object_.keys, nativeFloor = Math_.floor, toString = Object_.prototype.toString, slice = Array_.prototype.slice, push = Array_.prototype.push, fromCharCode = String.fromCharCode, parse = JSON.parse, now = Date.now, isFinite_ = context.isFinite, Symbol_ = context.Symbol, create = Object_.create, nativeIsBuffer = undefined;
var swapped = Math_.max; function swap() { swapped = Math_.min; }
var chosen = [1][0] ? Array_.isArray : Object_.keys;
const show = v => { try { return JSON.stringify(v) ?? String(v); } catch (e) { return e.name; } };
const rows = [() => isArray([]), () => isArray({ length: 0 }), () => isArray(new Proxy([], {})), () => isArray(), () => hasOwnProperty.call({ a: 1 }, "a"), () => hasOwnProperty.call({ a: 1 }, "b"), () => hasOwnProperty.call("ab", 1), () => hasOwnProperty.call(null, "a"), () => hasOwnProperty.apply({ a: 1 }, ["a"]), () => hasOwnProperty.call(new Proxy({}, { getOwnPropertyDescriptor() { return { value: 1, configurable: true }; } }), "x"),
  () => Array_(3).length, () => Array_(3, 4), () => Array_("3"), () => Array_(-1), () => Array_(1.5), () => new Array_(2).length, () => Array_(0), () => Array_(4294967296), () => { const a = Array_(2); a[0] = "s"; a[1] = 1.5; return a; }, () => Object_(1) instanceof Number, () => Object_(null), () => Object_("s").length, () => { const o = {}; return Object_(o) === o; },
  () => nativeMax(1, 0), () => nativeMax(), () => nativeMax(NaN, 1), () => nativeMax("3", 2), () => nativeMax(-0, 0), () => Object.is(nativeMin(0, -0), -0), () => nativeMax({ valueOf() { return 9; } }, 1), () => nativeMax(1n, 2), () => nativeKeys({ b: 1, a: 2 }), () => nativeKeys("ab"), () => nativeKeys(null), () => nativeFloor(-1.5), () => nativeFloor("x"), () => toString.call(null), () => toString.call([]), () => toString.call(function () {}), () => slice.call("abc", 1), () => slice.call({ 0: "a", length: 1 }), () => { const a = []; push.call(a, 1, 2); return a; }, () => { const o = { length: 1 }; push.call(o, "x"); return o; },
  () => fromCharCode(97, 98), () => fromCharCode(), () => fromCharCode(65536 + 97), () => parse("[1]"), () => parse("{"), () => typeof now(), () => isFinite_("1"), () => isFinite_(Infinity), () => typeof Symbol_("x"), () => create(null) instanceof Object, () => swapped(1, 2), () => chosen([]), () => isArray.call(null, []), () => isArray.length + isArray.name, () => nativeMax.apply(null, [1, 5, 3]), () => nativeMax.apply(null, { length: 2, 0: 7, 1: 8 }), () => Reflect.apply(nativeMax, null, [1, 2]), () => [[], {}].map(isArray), () => [1.5, 2.5].map(nativeFloor), () => typeof nativeIsBuffer];
for (let round = 0; round < 3; round++) { if (round === 2) swap(); rows.forEach((f, i) => { let text; try { text = show(f()); } catch (e) { text = "THROWS " + e.name; } if (round !== 1) console.log(round, i, text); }); }
'''
os.makedirs(out + "/builtins-in-variables", exist_ok=True); open(out + "/builtins-in-variables/main.js", "w").write(BV)
print(4, "programs")
